<script setup lang="ts">
import { computed } from 'vue'
import { useRouter } from 'vue-router'
import { Activity, ArrowRight, Bell, CarFront, ChevronRight, CircleGauge, CloudOff, Navigation, RefreshCw, TrendingUp, Zap } from 'lucide-vue-next'
import PageHeader from '../components/common/PageHeader.vue'
import MetricCard from '../components/common/MetricCard.vue'
import StatePanel from '../components/common/StatePanel.vue'
import StatusBadge from '../components/common/StatusBadge.vue'
import VehicleArt from '../components/vehicle/VehicleArt.vue'
import VectorMap from '../components/map/VectorMap.vue'
import EChart from '../components/charts/EChart.vue'
import { useFleetStore } from '../stores/fleet'
import { useUiStore } from '../stores/ui'
import { useOnline } from '../composables/useOnline'
import { formatTime, relativeTime, shortVin } from '../utils/format'
const fleet = useFleetStore(), ui = useUiStore(), router = useRouter()
const { online } = useOnline()
const chartColor = computed(() => ui.theme === 'dark' ? '#a79cff' : '#7163e8')
const energyOption = computed(() => ({ grid: { left: 38, right: 15, top: 28, bottom: 25 }, tooltip: { trigger: 'axis' as const }, xAxis: { type: 'category' as const, data: ['00:00','04:00','08:00','12:00','16:00','20:00','24:00'], axisLine: { show: false }, axisTick: { show: false }, axisLabel: { color: '#9298a9', fontSize: 9 } }, yAxis: { type: 'value' as const, splitLine: { lineStyle: { color: ui.theme==='dark'?'#2b3048':'#eceef4', type: 'dashed' as const } }, axisLabel: { color: '#9298a9', fontSize: 9, formatter: '{value}%' } }, series: [{ type: 'line' as const, data: [71,68,65,58,62,67,fleet.averageBattery], smooth: true, symbol: 'none', lineStyle: { width: 2.5, color: chartColor.value }, areaStyle: { color: { type: 'linear' as const, x: 0,y:0,x2:0,y2:1,colorStops:[{offset:0,color:ui.theme==='dark'?'rgba(145,132,255,.25)':'rgba(113,99,232,.20)'},{offset:1,color:'rgba(113,99,232,0)'}] } } }] }))
const modelStats = computed(() => {
  const groups = new Map<string,number>()
  fleet.vehicles.forEach(v => groups.set(v.model.split(' ')[0], (groups.get(v.model.split(' ')[0]) || 0) + 1))
  const colors = ['#7163e8','#27bcb5','#a8afc0','#e5a552']
  return [...groups.entries()].map(([name,value],i) => ({ name,value,itemStyle:{color:colors[i%4]} }))
})
const distributionOption = computed(() => ({ tooltip: { trigger: 'item' as const }, series: [{ type: 'pie' as const, radius: ['67%','85%'], center: ['50%','48%'], padAngle: 3, itemStyle: { borderRadius: 5 }, label: { show: false }, data: modelStats.value }] }))
async function refresh() { try { await fleet.load(true); ui.toast('车队快照已更新','success') } catch { /* state panel */ } }
</script>
<template>
  <div class="page overview-page">
    <PageHeader eyebrow="FLEET COMMAND CENTER" title="早上好，欢迎回到运营中心" subtitle="实时掌握车辆状态、能耗趋势与需要关注的运营事件。"><template #actions><span class="last-sync"><span class="dot"/>数据更新于 {{ formatTime(fleet.lastUpdated) }}</span><button class="btn btn-secondary" :disabled="fleet.loading" @click="refresh"><RefreshCw :class="{ spin: fleet.loading }"/>刷新数据</button></template></PageHeader>
    <StatePanel :loading="fleet.loading && !fleet.loaded" :error="fleet.error" :offline="!online && !fleet.loaded" @retry="fleet.load(true)">
      <div class="grid grid-4 metrics"><MetricCard label="授权车辆" :value="fleet.vehicles.length" unit="辆" :trend="8.2" hint="较上月" :points="[12,15,14,18,20,22,24]"><template #icon><CarFront/></template></MetricCard><MetricCard label="当前在线" :value="fleet.onlineCount" :unit="`/ ${fleet.vehicles.length}`" :trend="2.4" hint="在线率稳定" tone="cyan" :points="[18,19,18,21,22,23,24]"><template #icon><Activity/></template></MetricCard><MetricCard label="行驶中车辆" :value="fleet.movingCount" unit="辆" hint="实时速度大于 1 km/h" tone="green"><template #icon><Navigation/></template></MetricCard><MetricCard label="待处理告警" :value="fleet.openAlerts.length" unit="条" :trend="-12.5" hint="较昨日" tone="orange" :points="[12,10,13,8,7,5,4]"><template #icon><Bell/></template></MetricCard></div>
      <section class="hero-grid">
        <article class="card fleet-hero"><div class="hero-copy"><div class="eyebrow">AURORA CONNECTED</div><h2>每一公里，都清晰可见。</h2><p>车队平均电量 <strong>{{ fleet.averageBattery.toFixed(0) }}%</strong>，预计可支持 <strong>18,420</strong> 公里运营里程。</p><button class="btn btn-primary" @click="router.push('/fleet')">进入实时车队<ArrowRight/></button></div><div class="hero-car"><VehicleArt color="#8074f1"/></div><div class="hero-stat"><Zap/><div><small>今日累计行驶</small><strong class="numeric">2,864 <span>km</span></strong></div></div><div class="hero-ring ring-one"/><div class="hero-ring ring-two"/></article>
        <article class="card health-card"><div class="card-header"><div><h3 class="card-title">车队健康度</h3><p class="card-caption">基于在线、电量与故障综合评估</p></div><span class="badge badge-success">状态优秀</span></div><div class="health-score"><svg viewBox="0 0 140 90"><path d="M20 75a50 50 0 0 1 100 0" pathLength="100" class="score-track"/><path d="M20 75a50 50 0 0 1 100 0" pathLength="100" class="score-value"/></svg><div><strong class="numeric">96</strong><span>综合得分</span></div></div><div class="health-items"><div><span><i class="good"/>动力系统</span><strong>100%</strong></div><div><span><i class="good"/>网络连接</span><strong>{{ fleet.vehicles.length ? Math.round(fleet.onlineCount/fleet.vehicles.length*100) : 0 }}%</strong></div><div><span><i class="warn"/>耗材与保养</span><strong>92%</strong></div></div></article>
      </section>
      <div class="grid analytics-grid">
        <article class="card"><div class="card-header"><div><h3 class="card-title">车队电量趋势</h3><p class="card-caption">过去 24 小时平均 SOC 变化</p></div><span class="badge badge-info">24H</span></div><div class="card-body"><EChart :option="energyOption" :height="230"/></div></article>
        <article class="card distribution"><div class="card-header"><div><h3 class="card-title">车型分布</h3><p class="card-caption">当前授权车队构成</p></div></div><div class="distribution-body"><div class="donut"><EChart :option="distributionOption" :height="155"/><div><strong>{{ fleet.vehicles.length }}</strong><span>车辆总数</span></div></div><div class="distribution-legend"><div v-for="item in modelStats" :key="item.name"><span><i :style="{background:item.itemStyle.color}"/>{{ item.name }} 系列</span><strong>{{ item.value }} <small>辆</small></strong></div></div></div></article>
      </div>
      <div class="grid operations-grid">
        <article class="card map-preview"><div class="card-header"><div><h3 class="card-title">实时车辆分布</h3><p class="card-caption">上海运营区域 · {{ fleet.onlineCount }} 辆在线</p></div><button class="btn btn-ghost btn-sm" @click="router.push('/fleet')">展开地图<ChevronRight/></button></div><div class="card-body"><VectorMap :vehicles="fleet.vehicles.slice(0,5)" :telemetry="fleet.telemetry" :selected-vin="fleet.selectedVin" :height="295" @select="vin => router.push(`/vehicles/${vin}`)"/></div></article>
        <article class="card alert-preview"><div class="card-header"><div><h3 class="card-title">需要关注</h3><p class="card-caption">按严重程度与发生时间排序</p></div><RouterLink to="/alerts" class="text-link small">全部告警</RouterLink></div><div class="alert-list"><button v-for="alert in fleet.openAlerts.slice(0,4)" :key="alert.id" @click="router.push('/alerts')"><span class="alert-symbol" :class="alert.severity"><CloudOff v-if="alert.code==='VEHICLE_OFFLINE'"/><Bell v-else/></span><span><strong>{{ alert.title }}</strong><small>{{ shortVin(alert.vin) }} · {{ relativeTime(alert.occurred_at_ms) }}</small></span><ChevronRight/></button><div v-if="!fleet.openAlerts.length" class="all-clear"><CircleGauge/><strong>车队一切正常</strong><span>当前没有待处理告警</span></div></div><div class="alert-summary"><TrendingUp/><span>今日告警响应效率</span><strong>94.6%</strong></div></article>
      </div>
      <article class="card fleet-table"><div class="card-header"><div><h3 class="card-title">车辆动态</h3><p class="card-caption">授权范围内车辆的最新遥测快照</p></div><RouterLink to="/fleet" class="btn btn-secondary btn-sm">查看全部<ArrowRight/></RouterLink></div><div class="table-wrap"><table><thead><tr><th>车辆</th><th>连接状态</th><th>车速</th><th>剩余电量</th><th>续航里程</th><th>最后上报</th><th/></tr></thead><tbody><tr v-for="vehicle in fleet.vehicles.slice(0,5)" :key="vehicle.vin"><td><div class="vehicle-cell"><span class="mini-car"><CarFront/></span><div><strong>{{ vehicle.display_name }}</strong><small>{{ vehicle.model }}</small></div></div></td><td><StatusBadge :status="fleet.isOnline(vehicle.vin)?'online':'offline'" :pulse="fleet.isOnline(vehicle.vin)"/></td><td class="numeric"><strong>{{ Math.round(fleet.telemetry[vehicle.vin]?.speed_kph || 0) }}</strong> km/h</td><td><div class="table-battery"><span><i :style="{width:`${fleet.telemetry[vehicle.vin]?.battery_percent || 0}%`}"/></span>{{ fleet.telemetry[vehicle.vin]?.battery_percent.toFixed(0) || '—' }}%</div></td><td class="numeric">{{ fleet.telemetry[vehicle.vin]?.range_km || '—' }} km</td><td>{{ relativeTime(fleet.telemetry[vehicle.vin]?.occurred_at_ms) }}</td><td><button class="btn btn-ghost btn-icon btn-sm" @click="router.push(`/vehicles/${vehicle.vin}`)"><ChevronRight/></button></td></tr></tbody></table></div></article>
    </StatePanel>
  </div>
</template>
<style scoped>
